import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';import '../../../core/di/catalog_providers.dart';import '../../../core/presentation/catalog_cards.dart';class ServicesScreen extends ConsumerWidget{const ServicesScreen({super.key});@override Widget build(BuildContext c,WidgetRef r){final a=r.watch(servicesProvider(null));return Scaffold(appBar:AppBar(title:const Text('Services')),body:a.when(data:(items)=>items.isEmpty?const Center(child:Text('No services available')):ListView.builder(padding:const EdgeInsets.all(12),itemCount:items.length,itemBuilder:(_,i){final x=items[i] as Map<String,dynamic>;return CatalogCard(item:x,label:'Service',onTap:()=>c.push('/services/${x['id']}'));}),loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('Unable to load services: $e'))));}}
